samples := inputs["samples"].([]any)
if len(samples) == 0 { return nil, fmt.Errorf("need at least one sample") }
lo, hi := samples[0].(float64), samples[0].(float64)
for _, sample := range samples {
  n := sample.(float64)
  if n < lo { lo = n }; if n > hi { hi = n }
}
return map[string]any{"spread": hi-lo}, nil
